<?php require_once __DIR__ . '/../includes/auth.php'; require_admin(); require_once __DIR__ . '/../config/database.php'; require_once __DIR__ . '/../includes/functions.php'; $name=trim($_POST['name']??''); if(!preg_match('/^[A-Za-zÇĞİÖŞÜçğıöşü0-9\s]{2,100}$/u',$name)){set_flash('danger','Invalid name format.'); redirect('create.php');} $desc=trim($_POST['description']??''); $stmt=$conn->prepare('INSERT INTO departments(name,description) VALUES(?,?)'); $stmt->bind_param('ss',$name,$desc); $stmt->execute(); set_flash('success','Department created.'); redirect('index.php'); ?>
